def dataset(index, domain):
    name, brand, dimension, *rest = domain
    names, labels = rest[:4], rest[4:]
    base = (index+10)*100
    products=[]
    for n in range(4):
        prefix=f'V{index:02d}' if index else 'D00'
        lab=labels[n].split('|')
        products.append(dict(id=f'{prefix}-{n+1:02d}', name=names[n], category='Основные товары' if n<2 else 'Расходные материалы',
            manufacturer='Мастерская «'+brand+'»', material='Материал учебного изделия',
            description=f'{dimension}: {lab[0]} и {lab[1]}. Остатки учитываются вместе для одной модели.',
            basePrice=[base,base+200,base+100,10.02][n],
            stocks=[dict(label=lab[0],quantity=[2,2,1,1][n]),dict(label=lab[1],quantity=[4,3,3,2][n])]))
    return dict(organization=name+' «'+brand+'»',dimension=dimension,controlDate='2027-01-15',products=products,
        orders=[dict(productId=products[0]['id'],date='2026-12-01'),dict(productId=products[0]['id'],date='2026-12-31'),
                dict(productId=products[1]['id'],date='2027-01-01'),dict(productId=products[2]['id'],date='2026-11-30')])

