def render_page(p,anchor):
    blocks=''
    for x in p['blocks']:
        content='<pre>'+html.escape(x['text'])+'</pre>' if x['kind']=='code' else ''.join('<p>'+html.escape(t)+'</p>' for t in x['text'].split('\n\n'))
